-- 1) Renumber: Body Weight Development 5 -> 1, 1 -> 2, 2 -> 3
update coaching_tools set title = case title
    when 'Body Weight Development 5' then 'Body Weight Development 1'
    when 'Body Weight Development 1' then 'Body Weight Development 2'
    when 'Body Weight Development 2' then 'Body Weight Development 3' end
where title in ('Body Weight Development 1', 'Body Weight Development 2', 'Body Weight Development 5')
  and category = 'Body weight development';

-- 2) Tiny's Exercise List (from the spreadsheet)
insert into coaching_tools (title, description, category, kind, body)
select 'Tiny''s Exercise List', 'Tiny''s classes: expectations, warm-ups, body weight sets, leg control, WuShu, core levels, fitness tests and games', 'Body weight development', 'page', '<h2>Class expectations</h2><ul><li>Sit smart</li><li>Standing strong</li><li>Listening</li><li>No talking when coach is talking</li><li>Concentration</li><li>Work hard</li></ul><h2>Warm-up &amp; agility</h2><ul><li>Star jumps</li><li>Ali shuffles</li><li>2 in 2 out</li><li>Squat hold</li><li>Lunge hold</li><li>Bridge</li><li>Single leg bridge</li><li>Shimmy jumps</li><li>Shimmy hops</li><li>Mat end agility jumps (with spots)</li><li>Balance beams (mat ends)</li></ul><h2>Body weight — set A</h2><ul><li>High plank</li><li>Side plank</li><li>Bridge hold</li><li>Push ups - incline</li><li>Shoulder push hold</li><li>Palm squeeze</li><li>Grip and pull</li><li>Squats</li><li>High knee hold</li><li>Standing side leg raises</li><li>Single leg RDL hold (superman)</li><li>Squat jumps (Ninja feet)</li></ul><h2>Leg control &amp; kicking drills</h2><ul><li>Foot to floor</li><li>Foot off the floor</li><li>Iso hold</li><li>Iso lifts</li><li>Figure eights</li><li>Infinities</li><li>Plank kicks</li><li>Level changes</li><li>Pyramids</li><li>Machine guns</li><li>Triggers</li></ul><h2>WuShu</h2><ul><li>WuShu forward (full)</li><li>WuShu sideways (full)</li><li>WuShu forward (pulse)</li><li>WuShu sideways (pulse)</li></ul><h2>Body weight — set B</h2><ul><li>Stretch flow</li><li>High plank</li><li>Side plank pick ups</li><li>Bridge hold</li><li>Push ups</li><li>Shoulder push ups</li><li>Quarter push ups</li><li>Snake push ups</li><li>Plyo push ups</li><li>Squats</li><li>Standing side leg raises</li><li>Sumo squats</li><li>Standing side leg raises off the floor</li><li>Lunge pulse</li><li>Wall sits</li><li>Squat jumps</li><li>Crunches</li></ul><h2>Core progressions (levels 1–5)</h2><table><thead><tr><th>Level</th><th>Front</th><th>Side</th><th>Bridge</th></tr></thead><tbody><tr><td>1</td><td>Flat plank</td><td>Side plank</td><td>Bridge</td></tr><tr><td>2</td><td>Superman</td><td>Side plank top leg</td><td>Bridge single leg</td></tr><tr><td>3</td><td>Shoulder taps</td><td>Side plank with abduction</td><td>Bridge with hip raise</td></tr><tr><td>4</td><td>Plank with abduction</td><td>Side plank with rotation</td><td>Bridge single leg with hip raise</td></tr><tr><td>5</td><td>Rattlers</td><td>Side plank oblique lift</td><td>Bridge</td></tr></tbody></table><h2>Core circuit</h2><ol><li>Crunches</li><li>Toe touches (medicine ball)</li><li>Tri push ups (medicine ball)</li><li>Squats (punch bag)</li><li>Reverse lunge</li><li>Dorsal raise</li><li>Hip raises</li><li>Shoulder press (stability ball)</li><li>Rattlers</li><li>Reverse single leg squat thrusts</li><li>Feet up?</li><li>Dorsal punches (4 punches)</li><li>Leg raises (stability ball)</li><li>Push ups (med ball and fist)</li><li>Side crunches</li><li>Side crunches</li><li>Crunch hold and nods</li><li>Nods</li><li>Turn hold</li><li>Turn hold</li></ol><h2>Fitness tests</h2><ul><li>Dips</li><li>Full sit up</li><li>Squats</li><li>Flat plank</li><li>Side plank - right up</li><li>Side plank - left up</li><li>The pole - back to wall</li><li>Left grip</li><li>Right grip</li><li>Left pinch</li><li>Right pinch</li><li>Left front kick figure 8</li><li>Right front kick figure 8</li><li>Left side kick figure 8</li><li>Right side kick figure 8</li><li>Vertical jump</li><li>Long jump</li><li>Hamstring stretch</li><li>Box splits stretch</li></ul><h2>Games &amp; circuits</h2><ul><li>Spot race</li><li>Cone flip</li><li>Shimmy jump (spots)</li><li>Count the leader</li><li>Plank pad</li><li>Traffic lights</li><li>Noughts and crosses</li><li>Rock paper scissors</li><li>Head, shoulders, knees</li></ul>'
where not exists (select 1 from coaching_tools where title = 'Tiny''s Exercise List');

-- 3) Check
select title, kind from coaching_tools where category = 'Body weight development' order by title;
